func applyStaged(stagingDir string, dest *destTree, actions []FileAction) ([]string, error) {
	var written []string
	for _, a := range actions {
		if !a.Writes() {
			continue
		}
		if err := dest.assertWritable(a.Rel); err != nil {
			return written, err
		}
		src := filepath.Join(stagingDir, filepath.FromSlash(a.Rel))
		data, err := os.ReadFile(src)
		if err != nil {
			return written, fmt.Errorf("read staged %s: %w", a.Rel, err)
		}
		if err := dest.write(a.Rel, data); err != nil {
			return written, err
		}
		written = append(written, a.Rel)
	}
	return written, nil
}

// OverlaysSegment is the skeleton directory whose contents may legitimately
// differ between environments.
const OverlaysSegment = "overlays/"

// mergeRendered folds one environment's render into the unit's staged tree.
//
// A skeleton is rendered once per environment, because the renderer has no way to
// emit one overlays/<env>/ directory per value — paths are templated, not
// iterated. Everything outside overlays/ must therefore come out identical on
// every pass, and this is where that is enforced: a file that differs between two
// environments means the author used an environment-varying value somewhere it
// does not belong, and silently keeping the last pass would be a tree whose base/
// only matches one environment.
func mergeRendered(from, into, env string) error {
	return filepath.WalkDir(from, func(p string, d fs.DirEntry, err error) error {
		if err != nil {
			return err
		}
		rel, err := filepath.Rel(from, p)
		if err != nil {
			return err
		}
		if rel == "." {
			return nil
		}
		target := filepath.Join(into, rel)
		if d.IsDir() {
			return os.MkdirAll(target, 0o755)
		}

		next, err := os.ReadFile(p)
		if err != nil {
			return err
		}
		if current, err := os.ReadFile(target); err == nil {
			if string(current) == string(next) {
				return nil
			}
			slash := filepath.ToSlash(rel)
			if !strings.HasPrefix(slash, OverlaysSegment) {
				return fmt.Errorf("%s renders differently for environment %q than for an earlier one; a value that varies by environment may only be used under %s",
					slash, env, OverlaysSegment)
			}
		}
		if err := os.MkdirAll(filepath.Dir(target), 0o755); err != nil {
			return err
		}
		return os.WriteFile(target, next, 0o644)
	})
}

// componentRelPath is the repository-relative directory a component's manifests
// live in, slash-separated.
func componentRelPath(domain, system, component string) string {
	return gitops.Coordinate{Domain: domain, System: system, Component: component}.RelPath()
}

// summariseActions counts the actions by kind for the one-line report.
func summariseActions(actions []FileAction) string {
	counts := map[string]int{}
	for _, a := range actions {
		counts[a.Action]++
	}
	var parts []string
	for _, kind := range []string{ActionCreate, ActionConflict, ActionIdentical} {
		if n := counts[kind]; n > 0 {
			parts = append(parts, fmt.Sprintf("%d %s", n, kind))
		}
	}
	if len(parts) == 0 {
		return "nothing to do"
	}
	return strings.Join(parts, ", ")
}

package template

import (
	"fmt"
	"maps"
	"slices"
)

// Reserved value keys carry structured, non-parameter data into a render.
//
// spec.parameters is scalar-only by design, so a skeleton cannot declare "the
// list of connectors" as a parameter. These keys are how it gets one anyway:
// the caller injects the structures after validation, and the skeleton ranges
// over them. Which files a render produces is then decided by a spec.files
// condition over the same data.
const (
	ReservedTopologyKey  = "topology"
	ReservedComponentKey = "component"
	ReservedGitopsKey    = "gitops"
	ReservedScaffoldKey  = "scaffold"

	// ReservedEnvKey is the environment being rendered. Reserved rather than a
	// parameter because the caller supplies it, never the user — and because it
	// is the value most often needed in a *path* (`overlays/{{ .env }}/`), where
	// a nested lookup would read badly.
	ReservedEnvKey = "env"

	// ReservedLocalKey carries the local-render decisions — the per-connector
	// fixture bindings — into a render for the local development cluster.
	ReservedLocalKey = "local"
)

// InjectReserved adds structured, non-parameter data to a resolved value map.
//
// It must be called *after* Resolve/ResolveLayered, never before: the values it
// adds are lists and nested maps that spec.parameters cannot describe, so
// running them through JSON Schema validation would fail.
//
// A reserved key that collides with a declared parameter, a spec.values entry,
// or a value already in the map is refused — a template that read one thing
// while its schema documented another would be undebuggable. Nothing is
// injected when any key collides, so a caller never sees a half-populated map.
func InjectReserved(t *Template, values map[string]any, reserved map[string]any) error {
	declared := map[string]string{}
	for _, f := range t.Fields() {
		declared[f.Name] = "a declared parameter"
	}
	for name := range t.Spec.Values {
		declared[name] = "a spec.values entry"
	}

	// Sorted so a template with several collisions always reports the same one.
	keys := slices.Sorted(maps.Keys(reserved))
	for _, key := range keys {
		if what, collides := declared[key]; collides {
			return fmt.Errorf("reserved key %q collides with %s", key, what)
		}
		if _, present := values[key]; present {
			return fmt.Errorf("reserved key %q is already set; it cannot be supplied with --set or a values file", key)
		}
	}
	for _, key := range keys {
		values[key] = reserved[key]
	}
	return nil
}

